typedef void* tsd_data_t;
pthread_key_t key_handle;

/* Destructor run on thread exit if value set */
void cleanup_tsd(tsd_data_t data) { free(data); }

/* Key creation */
void setup() {
    pthread_key_create(&key_handle, cleanup_tsd);
    /* ... usage: pthread_setspecific(key_handle, data) */
}

/* --- Focus: Deleting the Key --- */

void shutdown_tsd_system() {
    /* Invalidates 'key_handle' globally.
       Prevents further use of the key.
       Destructors still run on active thread exit. */
    pthread_key_delete(key_handle);
}
